  Definition amframe : ltac2:(zQ "30!ig9!iie!io1>1M>0@1$1@1$0#k0@1$2@1$1@1$0#8P") := ltac2:(zQ "h30!ig9!iie!hd!io1!ki7!kk1!pf!kof!ktf!ime!ki0!kj2!lu0!kkd!lu5!lve!mg4!mgb!mh2\1M>0@1$1@1$0#k0@1$3@1$1@1$0#8@2$d@3$6@1$3@1$2@1$1@1$0#8@4$8$9^1@2$4@1$0#k0@2$a@2$b@1$0#k0?3sp0+j8N8@2$5@1$2@1$1@1$0#8@2$7N8@2$4@1$0#k0+hpgqpc>1i$c>0@2$f^1N8@2$e@1$1@1$0#k0\1w@1$1@1$0#k0@3$6@1$3@1$2@1$1@1$0#8@4$8$9^4@2$4@1$0#k0@2$h0@2$a@2$b@1$0#k0?3sp0+n8@2$h1+8@1$h2^3N8@2$5@1$2@1$1@1$0#8@2$7N8^1").

  Lemma aseg_X : forall s msF mo regs mem (status : word) K,
    getr regs 2 = Z_to_bv 64 (bv_unsigned sp0 - 128) -> getr regs 4 = Z_to_bv 64 0x6f1318 -> getr regs 8 = status ->
    stk_ok RSEGS mem (Z_to_bv 64 (bv_unsigned sp0 - 128)) MSTK -> aro_none mem -> arelro_none mem -> amframe mem ->
    (forall regs' msF' mo',
        as_VIS H s msF' = mkst regs' (Z_to_bv 64 0x191274) mem rom -> as_AKREL H s (mkCfg msF' mo') -> same_but_materialized mo mo' ->
        getr regs' 2 = Z_to_bv 64 (bv_unsigned sp0 - 48) -> getr regs' 4 = Z_to_bv 64 0x6f1318 -> getr regs' 10 = status ->
        getr regs' 1 = Z_to_bv 64 0x190aa0 ->
        realizes asegs (mkCfg msF' mo') K) ->
    as_VIS H s msF = mkst regs (Z_to_bv 64 0xbeab8) mem rom -> as_AKREL H s (mkCfg msF mo) ->
