  Definition atr_call_regs : ltac2:(zQ "40!kl3!ig9!iqf!iie>4regs@2$2@1$1#5@1$3@1$1#k0>1A$0>3len$0>3cfg$0>3sb1$0P") := ltac2:(zQ "e2!ig9!iie!lhd!pf!li1!li9!lif!ki7!kkd!mg4!ki0!kl3!iqf!kj2&@2$7@1$0#k0@2$9@2$9@2$9^4+2^2+4&@2$7@1$0#k0@2$a@2$a^3+6^2\4regs@2$c@1$0#5@1$1@1$0#k0\1A$b\3len$b\3cfg$b\3sb1$b@2$8@3$3@1$1@1$0#k0@2$4^5@3$5@1$0#5+1Kv$2@2$6@1$0#5+1@2$7@1$0#k0+ruqj0@2$8@3$3@1$1@1$0#k0@2$4^5@3$5@1$0#5+2Kv$2@2$6@1$0#5+2@2$7@1$0#k0@2$a@2$d@1$0#k0?3sp0+o0@2$8@3$3@1$1@1$0#k0@2$4^5@3$5@1$0#5+4Kv$2@2$6@1$0#5+4@2$7@1$0#k0+mvhjh8@2$8@3$3@1$1@1$0#k0@2$4^5@3$5@1$0#5+8Kv$2@2$6@1$0#5+8@2$7@1$0#k0@2$9^4+2@2$8@3$3@1$1@1$0#k0@2$4^5@3$5@1$0#5+9Kv$2@2$6@1$0#5+9@2$7@1$0#k0^4@2$8@3$3@1$1@1$0#k0@2$4^5@3$5@1$0#5+aKv$2@2$6@1$0#5+a@2$7@1$0#k0@2$9^4+2@2$8@3$3@1$1@1$0#k0@2$4^5@3$5@1$0#5+bKv$2@2$6@1$0#5+b@2$7@1$0#k0^2@2$8@3$3@1$1@1$0#k0@2$4^5@3$5@1$0#5+cKv$2@2$6@1$0#5+c~0@2$8@3$3@1$1@1$0#k0@2$4^5@3$5@1$0#5+dKv$2@2$6@1$0#5+d~1@2$8@3$3@1$1@1$0#k0@2$4^5@3$5@1$0#5+h2Kv$2@2$6@1$0#5+h2@2$7@1$0#k0^2@2$8@3$3@1$1@1$0#k0@2$4^5@3$5@1$0#5+h3Kv$2@2$6@1$0#5+h3~0@2$8@3$3@1$1@1$0#k0@2$4^5@3$5@1$0#5+h4Kv$2@2$6@1$0#5+h4~1@3$3@1$1@1$0#k0@2$4^5@3$5@1$0#5+h5Kv$2@2$6@1$0#5+h5@2$7@1$0#k0^1").

  (* [comment removed for export] *)
  Lemma aseg_Hk : forall s msF mo regs mem (pp : word) (A cap : Z) (data : list byte) K,
    aclose_ret_regs regs pp A (Z.of_nat (length data)) cap ->
    (6 + hdr_cfg data <= Z.of_nat (length data))%Z -> (0 < A)%Z -> (A + Z.of_nat (length data) < 2 ^ 47)%Z ->
    abuf_bytes mem A data ->
    stk_ok RSEGS mem (Z_to_bv 64 (bv_unsigned sp0 - 128)) MSTK -> aro_none mem -> arelro_none mem ->
    rdn RSEGS mem (Z_to_bv 64 (bv_unsigned sp0 - 136)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 0xbe9b8)) ->
    (forall regs' mem' msF' mo',
        as_VIS H s msF' = mkst regs' (Z_to_bv 64 0xbeb8c) mem' rom -> as_AKREL H s (mkCfg msF' mo') -> same_but_materialized mo mo' ->
        atr_call_regs regs' A (Z.of_nat (length data)) (hdr_cfg data) (bv_swrap 8 (hdr_b data 1)) ->
        (forall r : reg, In r [22; 23; 24; 25; 26; 27]%list -> getr regs' r = getr regs r) ->
        frame_mod mem mem' (regL_w sp0) -> stk_ok RSEGS mem' (Z_to_bv 64 (bv_unsigned sp0 - 128)) MSTK ->
        realizes asegs (mkCfg msF' mo') K) ->
    as_VIS H s msF = mkst regs (Z_to_bv 64 0x1a33a0) mem rom -> as_AKREL H s (mkCfg msF mo) ->
